import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Codeunits","description":"","frontmatter":{},"headers":[],"relativePath":"codeunits/index.md","filePath":"codeunits/index.md"}`),a={name:`codeunits/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="codeunits" tabindex="-1">Codeunits <a class="header-anchor" href="#codeunits" aria-label="Permalink to “Codeunits”">​</a></h1><h2 id="what-is-a-codeunit" tabindex="-1">What Is a Codeunit? <a class="header-anchor" href="#what-is-a-codeunit" aria-label="Permalink to “What Is a Codeunit?”">​</a></h2><p>A codeunit is an AL object that contains reusable business logic and procedures that can be called from other Business Central objects.</p><p>Codeunits help us separate business logic from the user interface and database structure.</p><p>For example, imagine we are developing a customer management application.</p><p>We might need functionality to:</p><ul><li>Calculate customer discounts.</li><li>Validate customer information.</li><li>Update customer records.</li><li>Check customer eligibility.</li></ul><p>Instead of putting all this logic inside page triggers, we can organize it into codeunits.</p><h2 id="why-do-we-need-codeunits" tabindex="-1">Why Do We Need Codeunits? <a class="header-anchor" href="#why-do-we-need-codeunits" aria-label="Permalink to “Why Do We Need Codeunits?”">​</a></h2><p>Consider a scenario where we want to calculate a customer&#39;s discount.</p><p>We could implement the calculation directly inside the Customer Card page.</p><p>However, what happens if we also need that calculation in another page, a report, or another codeunit?</p><p>We would have to duplicate the logic.</p><p>Codeunits solve this problem by allowing us to write business logic once and reuse it wherever necessary.</p><h3 id="benefits" tabindex="-1">Benefits <a class="header-anchor" href="#benefits" aria-label="Permalink to “Benefits”">​</a></h3><ul><li><strong>Reusability:</strong> Write logic once and call it from multiple objects.</li><li><strong>Separation of concerns:</strong> Keep business logic separate from page layouts and database definitions.</li><li><strong>Maintainability:</strong> Changes to business logic can be made in one central location.</li><li><strong>Organization:</strong> Group related functionality into dedicated objects.</li></ul><h2 id="where-do-codeunits-fit-in-business-central" tabindex="-1">Where Do Codeunits Fit in Business Central? <a class="header-anchor" href="#where-do-codeunits-fit-in-business-central" aria-label="Permalink to “Where Do Codeunits Fit in Business Central?”">​</a></h2><p>Remember the main objects we&#39;ve discussed:</p><table tabindex="0"><thead><tr><th>Object</th><th>Responsibility</th></tr></thead><tbody><tr><td>Table</td><td>Defines and stores business data.</td></tr><tr><td>Page</td><td>Provides the user interface for interacting with data.</td></tr><tr><td>Page Extension</td><td>Extends an existing page.</td></tr><tr><td>Table Extension</td><td>Extends an existing table.</td></tr><tr><td>Codeunit</td><td>Contains reusable business logic.</td></tr></tbody></table><p>These objects work together.</p><p>For example, when a user opens the Customer Card:</p><ol><li>The page displays customer information from the Customer table.</li><li>The user performs an action.</li><li>The page calls a procedure in a codeunit.</li><li>The codeunit executes the required business logic.</li><li>The codeunit can read or modify Customer records using record variables.</li></ol><h2 id="codeunits-and-record-variables" tabindex="-1">Codeunits and Record Variables <a class="header-anchor" href="#codeunits-and-record-variables" aria-label="Permalink to “Codeunits and Record Variables”">​</a></h2><p>Codeunits can use the same record variables and methods we&#39;ve already learned.</p><p>For example, a codeunit could contain logic that:</p><ul><li>Retrieves a customer using <code>Get()</code>.</li><li>Checks customer information using record fields.</li><li>Updates customer information using <code>Validate()</code>.</li><li>Saves changes using <code>Modify()</code>.</li></ul><p>The important thing is that codeunits don&#39;t need to be associated with a particular table to work with its records.</p><p>They can declare their own record variables and interact with different tables.</p><h2 id="how-are-codeunits-executed" tabindex="-1">How Are Codeunits Executed? <a class="header-anchor" href="#how-are-codeunits-executed" aria-label="Permalink to “How Are Codeunits Executed?”">​</a></h2><p>Codeunits can be invoked from different parts of Business Central.</p><p>Common examples include:</p><ul><li><strong>Pages:</strong> A user clicks an action that calls codeunit functionality.</li><li><strong>Other codeunits:</strong> One codeunit calls functionality in another.</li><li><strong>Reports:</strong> A report invokes business logic during processing.</li><li><strong>Job queues:</strong> Codeunits can execute scheduled background tasks.</li><li><strong>Event subscribers:</strong> Codeunits can respond to events raised by other application objects.</li></ul><p>A codeunit can also have an <code>OnRun()</code> trigger, which executes when the codeunit itself is run.</p><p>We&#39;ll explore this when we start creating codeunits.</p><h2 id="important-things-to-remember" tabindex="-1">Important Things to Remember <a class="header-anchor" href="#important-things-to-remember" aria-label="Permalink to “Important Things to Remember”">​</a></h2><ul><li>A codeunit is a container for reusable AL business logic.</li><li>Codeunits help separate business logic from the user interface.</li><li>They contain procedures that can be called from other application objects.</li><li>They can work with record variables to retrieve, insert, modify, and delete database records.</li><li>They are not tied to a particular table unless explicitly configured.</li><li>Codeunits do not provide a user interface like pages.</li></ul><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-codeunit-object" target="_blank" rel="noreferrer">Codeunit Object – Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/codeunit/codeunit-data-type" target="_blank" rel="noreferrer">Codeunit Data Type</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/codeunit/devenv-onrun-codeunit-trigger" target="_blank" rel="noreferrer">OnRun Codeunit Trigger</a></li></ul>`,38)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};